pub mod http {
    //! What a flow returns to pick the status of an HTTP answer:
    //! `return Err(eda_runtime::http::HttpError::not_found("no such order").into());`
    //! Any other error is an internal error (500) whose details are only logged.

    #[derive(Debug)]
    pub struct HttpError {
        pub status: u16,
        pub message: String,
    }

    impl HttpError {
        pub fn new(status: u16, message: impl Into<String>) -> Self {
            Self {
                status,
                message: message.into(),
            }
        }

        pub fn bad_request(message: impl Into<String>) -> Self {
            Self::new(400, message)
        }

        pub fn unauthorized(message: impl Into<String>) -> Self {
            Self::new(401, message)
        }

        pub fn forbidden(message: impl Into<String>) -> Self {
            Self::new(403, message)
        }

        pub fn not_found(message: impl Into<String>) -> Self {
            Self::new(404, message)
        }

        pub fn conflict(message: impl Into<String>) -> Self {
            Self::new(409, message)
        }
    }

    impl std::fmt::Display for HttpError {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "{} {}", self.status, self.message)
        }
    }

    impl std::error::Error for HttpError {}
}

use std::future::Future;
use std::time::Duration;

use anyhow::{Context, Result, bail};
use rdkafka::admin::{AdminClient, AdminOptions, NewTopic, TopicReplication};
use rdkafka::client::DefaultClientContext;
use rdkafka::config::ClientConfig;
use rdkafka::consumer::{CommitMode, Consumer, StreamConsumer};
use rdkafka::message::{Header, Message as _, OwnedHeaders};
use rdkafka::producer::{FutureProducer, FutureRecord};
use rdkafka::types::RDKafkaErrorCode;

/// Attempts a handler gets before the record is parked on the dead-letter topic.
const MAX_ATTEMPTS: u32 = 3;

pub fn init_tracing() {
    use tracing_subscriber::EnvFilter;
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    tracing_subscriber::fmt().with_env_filter(filter).init();
}

pub fn env_or(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_string())
}

/// Random UUID v4 as a string, handy for generating identifiers in flows.
pub fn new_id() -> String {
    uuid::Uuid::new_v4().to_string()
}

pub struct TopicSpec {
    pub name: String,
    pub partitions: i32,
    pub replication: i32,
}

/// Creates the topics that do not exist yet. Retries while the broker is starting up.
pub async fn ensure_topics(brokers: &str, specs: &[TopicSpec]) -> Result<()> {
    let admin: AdminClient<DefaultClientContext> = ClientConfig::new()
        .set("bootstrap.servers", brokers)
        .create()
        .context("cannot create Kafka admin client")?;
    let topics: Vec<NewTopic<'_>> = specs
        .iter()
        .map(|s| NewTopic::new(&s.name, s.partitions, TopicReplication::Fixed(s.replication)))
        .collect();

    let mut attempt = 0;
    loop {
        attempt += 1;
        match admin.create_topics(&topics, &AdminOptions::new()).await {
            Ok(results) => {
                for result in results {
                    match result {
                        Ok(name) => tracing::info!("created topic {name}"),
                        Err((_, RDKafkaErrorCode::TopicAlreadyExists)) => {}
                        Err((name, code)) => bail!("cannot create topic {name}: {code}"),
                    }
                }
                return Ok(());
            }
            Err(e) if attempt < 10 => {
                tracing::warn!("Kafka not ready at {brokers} ({e}), retrying");
                tokio::time::sleep(Duration::from_secs(2)).await;
            }
            Err(e) => return Err(e).context(format!("Kafka unreachable at {brokers}")),
        }
    }
}

pub struct Producer {
    inner: FutureProducer,
}

impl Producer {
    pub fn new(brokers: &str) -> Result<Self> {
        let inner: FutureProducer = ClientConfig::new()
            .set("bootstrap.servers", brokers)
            .set("enable.idempotence", "true")
            .set("message.timeout.ms", "10000")
            .create()
            .context("cannot create Kafka producer")?;
        Ok(Self { inner })
    }

    /// Encodes `message` as protobuf and publishes it. Records with the same key land on
    /// the same partition and are therefore consumed in order.
    pub async fn publish<M: prost::Message>(
        &self,
        topic: &str,
        key: Option<&str>,
        message: &M,
    ) -> Result<()> {
        self.publish_bytes(topic, key.map(str::as_bytes), &message.encode_to_vec())
            .await
    }

    pub async fn publish_bytes(
        &self,
        topic: &str,
        key: Option<&[u8]>,
        payload: &[u8],
    ) -> Result<()> {
        self.publish_bytes_with_headers(topic, key, payload, &[]).await
    }

    /// Like [`Producer::publish_bytes`], with string headers (the dead-letter records carry the
    /// reason they were parked).
    pub async fn publish_bytes_with_headers(
        &self,
        topic: &str,
        key: Option<&[u8]>,
        payload: &[u8],
        headers: &[(&str, &str)],
    ) -> Result<()> {
        let mut record: FutureRecord<'_, [u8], [u8]> = FutureRecord::to(topic).payload(payload);
        if let Some(key) = key {
            record = record.key(key);
        }
        if !headers.is_empty() {
            record = record.headers(headers.iter().fold(OwnedHeaders::new(), |h, (key, value)| {
                h.insert(Header {
                    key,
                    value: Some(*value),
                })
            }));
        }
        self.inner
            .send(record, Duration::from_secs(5))
            .await
            .map_err(|(e, _)| anyhow::anyhow!("publish to {topic} failed: {e}"))?;
        Ok(())
    }
}

/// Consumes `topic` forever, decoding each record as `M` and calling `handler`.
///
/// Delivery is at-least-once: the offset is committed after the handler succeeded, or
/// after the record was parked on `<topic>.dlq` once `MAX_ATTEMPTS` attempts failed
/// (or when it cannot be decoded). If the dead-letter publish itself fails it is retried
/// until it succeeds. Make handlers idempotent.
pub async fn consume<M, F, Fut>(
    brokers: &str,
    group_id: &str,
    topic: &str,
    handler: F,
) -> Result<()>
where
    M: prost::Message + Default + Clone,
    F: Fn(M) -> Fut,
    Fut: Future<Output = Result<()>>,
{
    let consumer: StreamConsumer = ClientConfig::new()
        .set("bootstrap.servers", brokers)
        .set("group.id", group_id)
        .set("enable.auto.commit", "false")
        .set("auto.offset.reset", "earliest")
        .create()
        .context("cannot create Kafka consumer")?;
    consumer.subscribe(&[topic])?;
    let dlq = Producer::new(brokers)?;
    let dlq_topic = format!("{topic}.dlq");
    tracing::info!("consuming {topic} as group {group_id}");

    loop {
        let record = match consumer.recv().await {
            Ok(record) => record,
            Err(e) => {
                tracing::error!("Kafka error on {topic}: {e}");
                tokio::time::sleep(Duration::from_secs(1)).await;
                continue;
            }
        };
        let payload = record.payload().unwrap_or_default();

        let outcome = match M::decode(payload) {
            Err(e) => Err(anyhow::anyhow!("cannot decode record: {e}")),
            Ok(event) => run_with_retries(&handler, event).await,
        };
        if let Err(e) = outcome {
            tracing::error!(
                "giving up on record {topic}[{}]@{}: {e:#}; parking it on {dlq_topic}",
                record.partition(),
                record.offset()
            );
            // Never drop a record silently: keep trying until the dead-letter topic accepts it.
            // This blocks the partition, which is the safe choice for at-least-once delivery.
            while let Err(e) = dlq.publish_bytes(&dlq_topic, record.key(), payload).await {
                tracing::error!("cannot publish to {dlq_topic}: {e:#}; retrying");
                tokio::time::sleep(Duration::from_secs(2)).await;
            }
        }
        // A failed commit only means the record may be redelivered, which at-least-once allows.
        if let Err(e) = consumer.commit_message(&record, CommitMode::Async) {
            tracing::warn!("cannot commit offset on {topic}: {e}");
        }
    }
}

async fn run_with_retries<M, F, Fut>(handler: &F, event: M) -> Result<()>
where
    M: Clone,
    F: Fn(M) -> Fut,
    Fut: Future<Output = Result<()>>,
{
    let mut attempt = 1;
    loop {
        match handler(event.clone()).await {
            Ok(()) => return Ok(()),
            Err(e) if attempt < MAX_ATTEMPTS => {
                tracing::warn!("handler failed (attempt {attempt}/{MAX_ATTEMPTS}): {e:#}");
                tokio::time::sleep(Duration::from_millis(250 * 2u64.pow(attempt))).await;
                attempt += 1;
            }
            Err(e) => return Err(e),
        }
    }
}
